'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var randu = require( '@stdlib/random/base/randu' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var incrnancovariance = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var acc;
	var i;
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		acc = incrnancovariance();
		if ( typeof acc !== 'function' ) {
			b.fail( 'should return a function' );
		}
	}
	b.toc();
	if ( typeof acc !== 'function' ) {
		b.fail( 'should return a function' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::accumulator', pkg ), function benchmark( b ) {
	var acc;
	var x;
	var y;
	var v;
	var i;

	acc = incrnancovariance();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		x = ( randu() < 0.1 ) ? NaN : randu() * 10; // ~10% NaN
		y = ( randu() < 0.1 ) ? NaN : randu() * 10; // ~10% NaN
		v = acc( x, y );
		if ( v !== v && i > 1 ) {
			b.fail( 'accumulator should not return NaN once enough valid data' );
		}
	}
	b.toc();
	if ( v !== v ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
